package thunderbird

import (
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// tbHeader is the header Thunderbird writes at the top of prefs.js (Preferences.cpp's
// kPrefFileHeader, gecko-dev master read 2026-11-08), with eol for NS_LINEBREAK.
func tbHeader(eol string) string {
	return strings.Join([]string{
		"// Mozilla User Preferences", "",
		"// DO NOT EDIT THIS FILE.", "//",
		"// If you make changes to this file while the application is running,",
		"// the changes will be overwritten when the application exits.", "//",
		"// To change a preference value, you can either:",
		"// - modify it via the UI (e.g. via about:config in the browser); or",
		"// - set it within a user.js file in your profile.", "", "",
	}, eol)
}

// tbWritten is a prefs.js as Thunderbird writes one, server1 off (eol between lines): its header,
// then one user_pref line each, names and string values through StrEscape. It holds what real
// profiles hold: the tag names SetupLabelTags writes ($label1, nsMsgTagService.cpp), a tag key
// with its =20 encoding, a JSON value with escaped quotes, a signature with \r\n escapes, a raw
// tab and a raw non-ASCII letter in values (StrEscape leaves both as they are), the 32-bit
// number's two ends.
func tbWritten(eol string) string {
	bs := string(rune(0x5c))
	lines := []string{
		`user_pref("extensions.webextensions.uuids", "{` + bs + `"a@b.example` + bs + `":` + bs + `"1234` + bs + `"}");`,
		`user_pref("mail.account.account1.server", "server1");`,
		`user_pref("mail.accountmanager.accounts", "account1");`,
		`user_pref("mail.identity.id1.fullName", "Zo` + "ë" + "\t" + `Smith");`,
		`user_pref("mail.identity.id1.htmlSigText", "Best,` + bs + `r` + bs + `nZo` + bs + bs + `e");`,
		`user_pref("mail.server.server1.directory-rel", "[ProfD]ImapMail/imap.gmail.com");`,
		`user_pref("mail.server.server1.hostname", "imap.gmail.com");`,
		off1,
		`user_pref("mail.server.server1.type", "imap");`,
		`user_pref("mail.zz.max", 2147483647);`,
		`user_pref("mail.zz.min", -2147483648);`,
		`user_pref("mailnews.tags.$label1.color", "#ff2600");`,
		`user_pref("mailnews.tags.$label1.tag", "Important");`,
		`user_pref("mailnews.tags.to=20do.tag", "to do");`,
		`user_pref("mailnews.tags.version", 2);`,
	}
	return tbHeader(eol) + strings.Join(lines, eol) + eol
}

// tbProfile is a profile whose prefs.js is prefs and user.js user ("" for none).
func tbProfile(t *testing.T, prefs, user string) (string, string) {
	t.Helper()
	p := profileWith(t, prefs, "imap.gmail.com")
	if user != "" {
		writeAt(t, filepath.Join(p, "user.js"), user)
	}
	return p, filepath.Join(p, "ImapMail", "imap.gmail.com")
}

// covers: MA-1264, R9, S10
// The allow-list reads a file as Thunderbird writes it (the positive twin of the refusals below):
// prefs.js with Thunderbird's own header and lines, LF or CRLF, is read, server1 is off, and
// EnableOffline turns it on, rewriting only server1's line and keeping every other byte. With
// Thunderbird's `$label1` tag names, a `=20` tag key, `\"`, `\\`, `\r` and `\n` escapes, a raw tab
// and a raw letter outside ASCII in values, and the 32-bit number's two ends, none of which
// Thunderbird's parser reads otherwise. A narrower name rule (letters, digits, ".", "_", "-")
// would refuse every profile Thunderbird has set its tags up in, saying it was changed outside
// Thunderbird, which is false.
func TestTheAllowListReadsWhatThunderbirdWrites(t *testing.T) {
	for _, eol := range []string{"\n", "\r\n"} {
		t.Run(map[string]string{"\n": "LF", "\r\n": "CRLF"}[eol], func(t *testing.T) {
			prefs := tbWritten(eol)
			p, store := tbProfile(t, prefs, "// set by IT"+eol+`user_pref("mail.zz.other", true);`+eol)
			acct, err := AccountToEnable(p, store)
			if err != nil || acct.ServerKey != "server1" || acct.OfflineDownload {
				t.Fatalf("AccountToEnable on a file as Thunderbird writes it: %+v, %v", acct, err)
			}
			c, err := EnableOffline(p, "server1")
			if err != nil || !c.Changed || !accountOn(t, p, store) {
				t.Fatalf("EnableOffline: %+v, %v", c, err)
			}
			got, _ := os.ReadFile(filepath.Join(p, "prefs.js"))
			if want := strings.Replace(prefs, off1, on1, 1); string(got) != want {
				t.Fatalf("prefs.js is not the file with only server1's line changed:\n%q\nwant\n%q", got, want)
			}
		})
	}
}

// covers: MA-1264, R9, S10
// Accept only the shapes Thunderbird writes (the C0c pass round 4's R4-01 and R4-02, the lead's
// allow-list): any other line anywhere in prefs.js or user.js, a lone carriage return (CR), mixed
// LF and CRLF endings, a byte-order mark, an escape other than \\, \", \n and \r (the \u high
// surrogate of R4-02 among them), a number Thunderbird skips, and every comment, spacing and
// quoting shape Thunderbird never writes, means MailArchive cannot be sure what Thunderbird
// applies. Each is a HandEditedError from AccountToEnable, CheckOffline and EnableOffline, never
// "already on" and never Changed, with both files byte for byte and no backup, the account on or
// off. Thunderbird's parser reads R4-01's comment as ending at the CR and R4-02's string as ending
// at the quote after `\ud800\`, so each hides a statement MailArchive's old reader did not see.
func TestOnlyTheShapesThunderbirdWritesAreRead(t *testing.T) {
	bs := string(rune(0x5c))
	// Each case is a prefs.js body (after the account's own line), or a whole user.js, or (whole)
	// a whole prefs.js after Thunderbird's account lines.
	type shape struct{ file, body, what string }
	cases := map[string]shape{
		"R4-01: a // comment ended by a lone CR":     {"prefs.js", "// note\r" + off1 + "\n", whatLoneCR},
		"R4-01: a # comment ended by a lone CR":      {"prefs.js", "# note\r" + off1 + "\n", whatLoneCR},
		"R4-01: user.js, a // comment ended by a CR": {"user.js", "// set by IT\r" + off1 + "\n", whatLoneCR},
		"R4-01: user.js, CR-only line endings":       {"user.js", "// mine\r" + off1 + "\r", whatLoneCR},
		"R4-02: a high surrogate, then a backslash":  {"prefs.js", `user_pref("mail.zz", "` + bs + `ud800` + bs + `"); user_pref('` + offKey + `', false); //");` + "\n", whatEscape},
		"R4-02: a high surrogate, then two":          {"prefs.js", `user_pref("mail.zz", "` + bs + `ud800` + bs + bs + `"); ` + on1 + "\n", whatEscape},
		"R4-02: user.js, a high surrogate":           {"user.js", `user_pref("mail.zz", "` + bs + `ud800` + bs + `"); user_pref('` + offKey + `', false); //");` + "\n", whatEscape},
		"a \\u escape in a value":                    {"prefs.js", `user_pref("mail.zz", "Zo` + bs + `u00eb");` + "\n", whatEscape},
		"a \\x escape in a value":                    {"user.js", `user_pref("mail.zz", "` + bs + `x41");` + "\n", whatEscape},
		"a \\t escape in a value":                    {"prefs.js", `user_pref("mail.zz", "a` + bs + `tb");` + "\n", whatEscape},
		"a CRLF line in an LF file":                  {"prefs.js", `user_pref("mail.zz", 1);` + "\r\n", whatLoneCR},
		"an LF line in a CRLF file":                  {"user.js", "// mine\r\n" + `user_pref("mail.zz", 1);` + "\n" + `user_pref("mail.zy", 1);` + "\r\n", whatMixedEOL},
		"a byte-order mark in user.js":               {"user.js", "\xef\xbb\xbf" + `user_pref("mail.zz", 1);` + "\n", whatBOM},
		"a number one past the top":                  {"prefs.js", `user_pref("mail.zz", 2147483648);` + "\n", whatBigInt},
		"a number one past the bottom":               {"prefs.js", `user_pref("mail.zz", -2147483649);` + "\n", whatBigInt},
		"a plus sign":                                {"prefs.js", `user_pref("mail.zz", +1);` + "\n", whatNotWhole},
		"True":                                       {"user.js", `user_pref("` + offKey + `", True);` + "\n", whatNotWhole},
		"a tab before the statement":                 {"prefs.js", "\t" + `user_pref("mail.zz", 1);` + "\n", whatNotWhole},
		"a tab after the statement":                  {"prefs.js", `user_pref("mail.zz", 1);` + "\t\n", whatMore},
		"two statements on a line":                   {"prefs.js", `user_pref("mail.zz", 1); user_pref("mail.zy", 1);` + "\n", whatMore},
		"a comment after a statement":                {"user.js", on1 + " // set by IT\n", whatMore},
		"a block comment":                            {"prefs.js", "/* note */\n", whatComment},
		"a hash comment":                             {"user.js", "# note\n", whatComment},
		"single quotes":                              {"prefs.js", `user_pref('mail.zz', 1);` + "\n", whatNotWhole},
		"no space after the comma":                   {"prefs.js", `user_pref("mail.zz",1);` + "\n", whatNotWhole},
		"two spaces after the comma":                 {"prefs.js", `user_pref("mail.zz",  1);` + "\n", whatNotWhole},
		"a space before the parenthesis":             {"prefs.js", `user_pref ("mail.zz", 1);` + "\n", whatNotWhole},
		"a space before the semicolon":               {"prefs.js", `user_pref("mail.zz", 1) ;` + "\n", whatNotWhole},
		"an empty name":                              {"prefs.js", `user_pref("", 1);` + "\n", whatNotWhole},
		"a value with a single-quoted string":        {"prefs.js", `user_pref("mail.zz", 'a');` + "\n", whatNotWhole},
		"a backslash at the end of a value's line":   {"prefs.js", `user_pref("mail.zz", "a` + bs + "\n", whatSpanning},
		"text after the statement, no comment":       {"prefs.js", `user_pref("mail.zz", 1);x` + "\n", whatMore},
	}
	if len(cases) < 30 {
		t.Fatalf("only %d shapes", len(cases))
	}
	for name, tc := range cases {
		for _, on := range []bool{false, true} {
			what := name + map[bool]string{false: ", account off", true: ", account on"}[on]
			t.Run(what, func(t *testing.T) {
				p, store := uncertainProfile(t, tc.file, tc.body, on)
				shapeRefused(t, p, store, tc.file, tc.what)
			})
		}
	}

	// A byte-order mark is only ever at the start of the file, so prefs.js gets its own case.
	t.Run("a byte-order mark in prefs.js", func(t *testing.T) {
		p, store := tbProfile(t, "\xef\xbb\xbf"+tbWritten("\n"), "")
		shapeRefused(t, p, store, "prefs.js", whatBOM)
	})
}

// shapeRefused asserts that p, holding a line MailArchive cannot be sure of in file, is refused
// by AccountToEnable, CheckOffline and EnableOffline with a HandEditedError naming file and what,
// with both files byte for byte and no backup.
func shapeRefused(t *testing.T, p, store, file, what string) {
	t.Helper()
	prefsPath, userPath := filepath.Join(p, "prefs.js"), filepath.Join(p, "user.js")
	prefsBefore, _ := os.ReadFile(prefsPath)
	userBefore, userErr := os.ReadFile(userPath)
	untouched := func() bool {
		same := bytesStill(prefsPath, prefsBefore)() && absent(prefsPath+".mailarchive-bak")
		if userErr == nil {
			same = same && bytesStill(userPath, userBefore)()
		}
		return same
	}
	var h *HandEditedError
	acct, err := AccountToEnable(p, store)
	if !errors.As(err, &h) {
		t.Fatalf("AccountToEnable: %+v, %v; want a HandEditedError (never \"already on\")", acct, err)
	}
	refusedNaming(t, err, func() bool { return acct == nil && untouched() }, file, "changed nothing", what, "Thunderbird never writes")
	if err := CheckOffline(p, "server1"); !errors.As(err, &h) {
		t.Fatalf("CheckOffline: %v; want a HandEditedError", err)
	}
	c, err := EnableOffline(p, "server1")
	if !errors.As(err, &h) {
		t.Fatalf("EnableOffline: %+v, %v; want a HandEditedError (never \"already on\" or Changed)", c, err)
	}
	refusedNaming(t, err, func() bool { return !c.Changed && untouched() }, file, offKey, "changed nothing", what)
}
